/** <Icon name="phone" /> renders the design's SVG with no wrapper element, so the reference CSS selectors keep working. */
export default function Icon({ name, size, style, className }) {
  const i = ICONS[name]; if (!i) return null;
  const a = { ...i.a }; if (size) { a.width = size; a.height = size; } if (className) a.className = ((a.className || '') + ' ' + className).trim();
  return <svg {...a} style={style} aria-hidden={a['aria-label'] ? undefined : true} dangerouslySetInnerHTML={{ __html: i.h }} />;
}
export const Logo = () => <Icon name="logo" />;
